message.content:
{
  "claims": [
    {
      "claim": "Thomas Willis was born in 1621.",
      "britannica_quote": "was born at Great Bodwin, in Wiltfhire, in 1621",
      "verdict": "agrees",
      "wikipedia_quote": "(27 January 1621 – 11 November 1675)",
      "passage": 1,
      "note": "Wikipedia gives the full birth date 27 January 1621; Britannica's place name is an OCR rendering of Great Bedwyn, Wiltshire."
    },
    {
      "claim": "Thomas Willis studied at Christ Church, Oxford.",
      "britannica_quote": "and fluidied at Chrift-church college, Oxford.",
      "verdict": "agrees",
      "wikipedia_quote": "He graduated M.A. from Christ Church, Oxford in 1642.",
      "passage": 1,
      "note": "Both place him at Christ Church, Oxford (OCR: fluidied/chrift-church)."
    },
    {
      "claim": "In 1660 Thomas Willis became Sedleian professor of natural philosophy and took the degree of doctor of physic the same year.",
      "britannica_quote": "In 1660, he became Sedleian profeeffor of natural philosophy, and the fame year took the degree of doctor of phyfic.",
      "verdict": "not_found",
      "wikipedia_quote": null,
      "passage": null,
      "note": "The Wikipedia passages mention his M.A. (1642) and B. Med. (1646) but not the 1660 Sedleian professorship or doctor of physick."
    },
    {
      "claim": "Thomas Willis was one of the first members of the Royal Society.",
      "britannica_quote": "He was one of the first members of the Royal Society",
      "verdict": "agrees",
      "wikipedia_quote": "was a founding member of the Royal Society",
      "passage": 1,
      "note": "A founding member is one of the first members."
    }
  ]
}
